/* Buyer Map data — bundled at build time, Nov 8 2026.
   Sources (all free, no key, no per-hit billing):
   - City boundaries + city centres: Nominatim / OpenStreetMap (Data © OpenStreetMap
     contributors, ODbL 1.0), polygon_geojson=1, polygon_threshold=0.01,
     fetched Nov 8 2026. Boundary coordinates are GeoJSON order [lon, lat].
   - ZIP centroids: U.S. Census Bureau, 2025 Gazetteer File, ZIP Code
     Tabulation Areas (ZCTA), national file 2025_Gaz_zcta_national.txt —
     GEOID + INTPTLAT/INTPTLONG (the ZCTA internal point, used as the ZIP
     centroid). U.S. federal government work: PUBLIC DOMAIN (17 U.S.C. § 105),
     no licence restriction on bundling. 6,722 of the 6,981 distinct ZIPs in
     the buyer data have a ZCTA (Nov 8 2026 build).
   SIMPLIFICATIONS (documented, not hidden):
   - Greenville NC: the OSM boundary is a MultiPolygon of ~23 parts; ALL outer
     rings are bundled, but the ~55 sub-200m hole slivers inside the main part
     were dropped — invisible at city zoom, they do not change the outline.
   - Pins are plotted at ZIP centroids (see zipCoords). Buyer street addresses
     are NOT geocoded yet — that is a one-time build-time geocode pass, still
     owed. A buyer whose ZIP has no centroid entry is NEVER placed anywhere:
     it shows in the list as unplotted. 259 buyer ZIPs (372 buyers) have no
     ZCTA — USPS-only ZIPs (PO-box / unique / post-2020) with no Census
     delineation — and 5,073 buyers have no usable ZIP at all ("00000" or
     blank). Those stay unplotted, honestly.
   - ZCTA internal points replace the 12 Nominatim postcode centroids bundled
     in the first build. Both are valid centroids; the switch to one source
     (Census, public domain) keeps a single source of truth. Max drift vs the
     old Nominatim values was 1.55 km (46203). */
